def svc_grid(B, lang, items):
    L = lambda k: B.path_of(lang, k)  # noqa: E731
    more = "Μάθετε περισσότερα" if lang == "el" else "Learn more"
    return '<div class="svc">%s</div>' % "".join(
        '<a href="%s">%s<span><b>%s</b><small>%s</small><i>%s →</i></span></a>' % (L(k), B.ill(n, lang, alt=""), t, s, more) for k, n, t, s in items)


def boards(rows):
    return '<div class="boards">%s</div>' % "".join(
        '<div class="board" style="--c:%s"><small>%s</small><b>%s</b><p>%s</p></div>' % r for r in rows)


